static ultrasonic_motiondetector_event ultrasonic_MotionDetector_get_next_event(Ultrasonic_MotionDetector* handle)
{
	ultrasonic_motiondetector_event next_event;
	ultrasonic_motiondetector_event_init(&next_event, Ultrasonic_MotionDetector_invalid_event);
	if(ultrasonic_motiondetector_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = ultrasonic_motiondetector_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean ultrasonic_MotionDetector_dispatch_next_event(Ultrasonic_MotionDetector* handle)
{
	ultrasonic_motiondetector_event nextEvent;
	nextEvent = ultrasonic_MotionDetector_get_next_event(handle);
	return ultrasonic_MotionDetector_dispatch_event(handle, &nextEvent);
}

